<?php require_once __DIR__.'/../_bootstrap.php';admin();$s=db()->query('SELECT id,full_name,shop_name,phone,email,role,status,trial_ends_at,subscription_start_at,subscription_end_at,subscription_status,created_at FROM users ORDER BY created_at DESC');$rows=$s->fetchAll();foreach($rows as &$row){$end=$row['subscription_end_at']?:$row['trial_ends_at'];$row['days_remaining']=$row['role']==='admin'?null:($end?max(0,(int)ceil((strtotime($end)-time())/86400)):0);$row['days_type']=$row['subscription_end_at']?'subscription':'trial';}out(['success'=>true,'users'=>$rows]);
